{
  "technical_and_design_decisions": [
    "Represent undeployed as a distinct deployment status value rather than mapping it to unknown.",
    "Apply undeployed when a stream has no deployment context associated with it; preserve existing statuses when deployment context is available.",
    "Implement the status behavior consistently for the CF, Lattice, Kubernetes, and Mesos SPIs.",
    "Create independent repositories for the Lattice, Kubernetes, and Mesos SPI implementations, preserving their existing build, packaging, and version-control history where practical.",
    "Use the existing project conventions for Java version, build tooling, dependency management, API compatibility, and CI configuration.",
    "Add unit and integration-level coverage for status conversion, no-deployment-context handling, and repository-specific behavior.",
    "Treat the existing Mesos SPI implementation as the basis for a pull request, with only the changes needed to make it build, test, and integrate with the separated repository structure."
  ],
  "assumptions": [
    "The existing codebase and Mesos SPI work are available locally and can be inspected without reconstructing missing functionality.",
    "The four deployers in scope are Cloud Foundry, Lattice, Kubernetes, and Mesos; no additional deployer implementations are included.",
    "Repository creation includes project extraction or migration, build configuration, CI setup, basic metadata, and verification, but not extensive community or release-management work.",
    "The existing status model can be extended without a major persistence migration or incompatible public API redesign.",
    "No changes are required to external platform APIs or to deployment infrastructure beyond the SPI repositories and application logic.",
    "Pull-request review is performed by others, but the estimate includes preparing the PR and addressing one normal review cycle.",
    "Documentation is limited to developer-facing README, status semantics, setup, and migration notes.",
    "All estimates represent active individual developer work-hours and exclude elapsed waiting time for approvals, external reviews, or CI queues."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Codebase discovery and implementation planning",
      "activity_description": "Inspect the existing admin project, SPI implementations, status model, deployment-context handling, tests, build configuration, and the existing Mesos work. Produce an implementation plan and identify affected interfaces and compatibility risks.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Status model and cross-deployer design",
      "activity_description": "Define the undeployed status semantics, precedence rules relative to unknown and deployed states, API representation, serialization behavior, and the common implementation approach across all in-scope deployers.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Create and initialize separate SPI repositories",
      "activity_description": "Extract or establish independent repositories for Lattice, Kubernetes, and Mesos, including source layout, build files, dependency configuration, CI, versioning metadata, ownership metadata, and preservation of required existing functionality.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A4",
      "activity_name": "Prepare and submit Mesos SPI pull request",
      "activity_description": "Bring the existing Mesos SPI work into the separated repository structure, complete missing integration and build details, prepare the change set, and submit a reviewable pull request.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement undeployed status for Cloud Foundry SPI",
      "activity_description": "Update Cloud Foundry status calculation and representation so streams without deployment context are reported as undeployed instead of unknown, including required API and serialization changes.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement undeployed status for Lattice SPI",
      "activity_description": "Update the Lattice SPI status calculation and related models or adapters to emit undeployed for streams lacking deployment context.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement undeployed status for Kubernetes SPI",
      "activity_description": "Update Kubernetes SPI status calculation and related models or adapters to emit undeployed for streams lacking deployment context.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement common undeployed behavior across deployers",
      "activity_description": "Apply the shared semantics consistently across all four deployers, including Mesos, and resolve differences in deployment-context detection, status mapping, and compatibility behavior.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Automated testing",
      "activity_description": "Add or update unit, component, and repository-level tests for the new status, no-deployment-context cases, existing deployed and unknown cases, repository builds, and cross-deployer consistency.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation and migration updates",
      "activity_description": "Update developer documentation, repository README files, status descriptions, setup instructions, and notes for consumers moving from the bundled project to separate SPI repositories.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A11",
      "activity_name": "End-to-end validation and review fixes",
      "activity_description": "Run all builds and CI checks, perform integration validation, inspect compatibility and packaging results, address defects and one expected review cycle, and finalize the increment for merge.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 120
  }
}

